  value: TodoFilterValue
  onChange: (value: TodoFilterValue) => void
}

const options: { value: TodoFilterValue; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'open', label: 'Open' },
  { value: 'done', label: 'Done' },
]

export const TodoFilter = ({ value, onChange }: TodoFilterProps) => (
  <div role="group" aria-label="Filter todos">
    {options.map((option) => (
      <button
        key={option.value}
        type="button"
        aria-pressed={value === option.value}
        onClick={() => onChange(option.value)}
      >
        {option.label}
      </button>
    ))}
  </div>
)
