import type { TodoGateway } from './TodoGateway'
import type { TodoViewModel } from './TodoViewModel'

export class AddTodo {
  private readonly todos: TodoGateway

  constructor(todos: TodoGateway) {
    this.todos = todos
  }

  async execute(title: string): Promise<TodoViewModel> {
    const trimmed = title.trim()
    if (!trimmed) throw new Error('A todo needs a title')
    const record = await this.todos.add(trimmed)
    return { id: record.id, title: record.title, status: record.done ? 'done' : 'open' }
  }
}
