import { useState } from 'react'

import { ErrorMessage } from '../../../shared/ui/ErrorMessage/ErrorMessage'
import { AddTodoForm } from '../AddTodoForm/AddTodoForm'
import { TodoFilter, type TodoFilterValue } from '../TodoFilter/TodoFilter'
import { TodoItem } from '../TodoItem/TodoItem'
import { useTodos } from '../useTodos/useTodos'

export const TodoList = () => {
  const state = useTodos()
  const [filter, setFilter] = useState<TodoFilterValue>('all')

  if (state.status === 'loading') return <p>Loading todos…</p>
  if (state.status === 'failed') return <ErrorMessage>The todos could not be loaded.</ErrorMessage>

  const visible = state.todos.filter((todo) => filter === 'all' || todo.status === filter)

  return (
    <>
      <TodoFilter value={filter} onChange={setFilter} />
      <AddTodoForm onAdd={state.add} />
      {visible.length > 0 ? (
        <ul aria-label="Todos">
          {visible.map((todo) => (
            <TodoItem key={todo.id} todo={todo} />
          ))}
        </ul>
      ) : (
        <p>{state.todos.length > 0 ? 'No matching todos.' : 'No todos yet.'}</p>
      )}
    </>
  )
}
